parameters.jsCode:
// The last line of defence on web-derived data before it leaves this workflow:
// fixed fields only, short single-line strings, a well-formed email on the
// company's own domain, no duplicates.
const MAX_FIELD = 200;
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const clean = (v) => String(v ?? '').replace(/[\r\n\t]+/g, ' ').trim().slice(0, MAX_FIELD);
const bareDomain = (v) => clean(v).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');

const raw = ($input.first().json.output || {}).leads;
const max = Number($('When Called by Orchestrator').first().json.max_leads) || 5;
const seen = new Set();
const leads = [];

for (const l of Array.isArray(raw) ? raw : []) {
  const lead = {
    company: clean(l.company),
    domain: bareDomain(l.domain),
    contact_name: clean(l.contact_name),
    contact_email: clean(l.contact_email).toLowerCase(),
    title: clean(l.title),
    reason: clean(l.reason),
  };
  if (!lead.company || !lead.domain || !emailRe.test(lead.contact_email)) continue;
  const emailDomain = lead.contact_email.split('@')[1];
  if (emailDomain !== lead.domain && !emailDomain.endsWith('.' + lead.domain)) continue;
  if (seen.has(lead.contact_email)) continue;
  seen.add(lead.contact_email);
  leads.push(lead);
}

const kept = leads.slice(0, max);
return [{ json: { count: kept.length, leads: kept } }];
